mapper.select:
SELECT l.*, s.name AS store_name, s.platform FROM ecom_listing l JOIN ecom_store s ON s.id = l.store_id WHERE NOT AND l.status <> 'DELETED' AND l.store_id = #{storeId}
AND (l.seller_sku LIKE CONCAT('%', #{keyword}, '%') OR l.title LIKE CONCAT('%', #{keyword}, '%') OR l.platform_item_id LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY l.store_id, l.seller_sku

SELECT o.id FROM ecom_order o
WHERE o.local_status = 'EXCEPTION'
AND o.store_id = #{storeId}
ORDER BY o.id
LIMIT #{limit}
